class Axis:

    def __init__(self, name, motor, mm_per_deg, lo, hi):
        self.name = name
        self.m = motor
        self.k = mm_per_deg
        self.lo = lo
        self.hi = hi
        self.timeout = 0
        self.target = 0.0
