    def expected_ms(self, dist_mm, speed):
        mm_per_s = abs(self.k) * 720.0 * speed / 100.0
        return 2000.0 * abs(dist_mm) / mm_per_s + 1500

    def deg(self):
        return self.m.position(DEGREES)

    def mm(self):
        return self.deg() * self.k

    def jog(self, speed):
        self.m.spin(FORWARD, speed, PERCENT)

    def halt(self):
        self.m.stop()

